"autoimmune thyroiditis","type 1 diabetes","autoimmune hepatitis","cytopenia (autoimmune)",
"lymphoproliferation or lymphadenopathy","central nervous system involvement","recurrent infections",
"elevated inflammatory markers (CRP/ESR)","autoantibodies (ANA/other)","growth failure",
"pericarditis or other serositis","interstitial lung disease","vasculitis"]

LAB1 = "unnamed person 1"
SPAN1 = "a patient who received autologous HCT because of central nervous system vasculitis relapsed after 18 months of remission and various immunosuppressive agents were reinitiated (30)"
LAB2 = "unnamed person 2"
SPAN2 = "The first case of allogeneic HCT was a 14-year-old English boy."
LAB3 = "unnamed person 3"
SPAN3 = "The second case was a 6-year-old Japanese boy."

# (feature, status, evidence_basis) per person; everything else not reported
P1 = {"central nervous system involvement": ("observed", "stated for this individual")}
P2 = {"type 1 diabetes": ("observed", "stated for this individual"),
      "interstitial lung disease": ("observed", "stated for this individual")}
P3 = {"genital ulcers": ("observed", "stated for this individual"),
      "arthritis or arthralgia": ("observed", "stated for this individual"),
      "skin lesions (rash, folliculitis, erythema nodosum)": ("observed", "stated for this individual")}

rows = []
for lab, span, spec in ((LAB1, SPAN1, P1), (LAB2, SPAN2, P2), (LAB3, SPAN3, P3)):
    for f in FEATURES:
        if f in spec:
            st, eb = spec[f]
        else:
            st, eb = "not reported", "not reported"
        rows.append({
            "pmid": {"value": "34899744", "span": "PMID: 34899744"},
            "individual_label_in_paper": {"value": lab, "span": span},
            "checklist_feature": {"value": f, "span": None},
            "status": {"value": st, "span": None},
            "evidence_basis": {"value": eb, "span": None},
        })

data = json.load(open(OUT, encoding="utf-8"))
data["tables"]["phenotype_checklist"] = rows
json.dump(data, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)

# --- validation ---
data = json.load(open(OUT, encoding="utf-8"))
schema = json.load(open("/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ha20_v5.json", encoding="utf-8"))
fields = {t["name"]: [f["name"] for f in t["fields"]] for t in schema["tables"]}
problems = []
def check_span(s):
    if s is None: return
    if isinstance(s, list):
        for x in s: check_span(x)
        return
    if s not in text:
        problems.append("SPAN NOT FOUND: " + repr(s[:80]))
for tname, trows in data["tables"].items():
    for i, r in enumerate(trows):
        if list(r.keys()) != fields[tname]:
            problems.append("%s row %d field mismatch: %s" % (tname, i, list(r.keys())))
        for k, cell in r.items():
            if "span" in cell: check_span(cell["span"])
labs = set()
for r in data["tables"]["individuals"]:
    labs.add(r["individual_label_in_paper"]["value"])
for tname in ("variants", "phenotypic_features", "phenotype_checklist"):
    for r in data["tables"][tname]:
        if r["individual_label_in_paper"]["value"] not in labs:
            problems.append("unknown label in %s: %s" % (tname, r["individual_label_in_paper"]["value"]))
print("rows per table:", {k: len(v) for k, v in data["tables"].items()})
print("problems:", len(problems))
for p in problems: print(p)
